// ==UserScript==
// @name         KEN BYPASS
// @namespace    ken-bypass
// @version      1.1.0
// @description  KEN BYPASS: nhận diện nút G, theo dõi CAPTCHA thủ công, tự đếm giờ và trích xuất mã hiển thị.
// @match        https://gtraffic.io/*
// @match        https://www.google.com/*
// @match        https://google.com/*
// @match        https://*.google.com/*
// @run-at       document-idle
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_setClipboard
// ==/UserScript==

(() => {
  'use strict';

  const STORE = {
    url: 'ken_bypass_last_url',
    delay: 'ken_bypass_delay',
    active: 'ken_bypass_active',
    clicked: 'ken_bypass_clicked',
    started: 'ken_bypass_started_at',
    waiting: 'ken_bypass_waiting_manual'
  };
  const DEFAULT_DELAY = 68;
  const BANNER = 'data:image/jpeg;base64,';
  const LOGO = 'data:image/jpeg;base64,';
  const G_ICON = 'data:image/jpeg;base64,';
  const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
  const get = (key, fallback = '') => {
    try { return GM_getValue(key, fallback); } catch (_) { return fallback; }
  };
  const set = (key, value) => {
    try { GM_setValue(key, value); } catch (_) {}
  };
  const isGtraffic = /(^|\.)gtraffic\.io$/i.test(location.hostname);
  const isGoogle = /(^|\.)google\.[a-z.]+$/i.test(location.hostname);

  const css = `
    #ken-bypass-root{position:fixed;z-index:2147483647;right:12px;top:90px;width:min(360px,calc(100vw - 24px));font:14px/1.4 Arial,sans-serif;color:#fff}
    #ken-bypass-root *{box-sizing:border-box}
    #ken-bypass-panel{background:linear-gradient(145deg,#07152f,#050914 75%);border:2px solid #e9a52b;border-radius:18px;box-shadow:0 0 18px #087cff88,0 8px 30px #000b;overflow:hidden}
    #ken-bypass-head{height:66px;display:flex;align-items:center;gap:9px;padding:7px 10px;background:#050b1c;cursor:move;border-bottom:1px solid #d89428}
    #ken-bypass-head img{width:46px;height:46px;object-fit:cover;border-radius:50%;border:1px solid #eeb63d}
    #ken-bypass-head strong{font-size:20px;letter-spacing:1px;font-weight:900;background:linear-gradient(90deg,#fff,#ffd338);color:transparent;background-clip:text}
    #ken-bypass-head .ken-spacer{flex:1}
    #ken-bypass-head .ken-iconbtn img{width:100%;height:100%;object-fit:cover;border-radius:8px;display:block}
    #ken-bypass-mini{position:relative}
    #ken-bypass-mini .ken-mini-plus{position:absolute;right:3px;bottom:3px;width:22px;height:22px;border-radius:6px;overflow:hidden;border:1px solid #eeb63d;background:#06152f}
    #ken-bypass-mini .ken-mini-plus img{width:100%;height:100%;object-fit:cover}
    .ken-iconbtn{border:1px solid #d99a2b;background:#101d38;color:white;border-radius:9px;width:31px;height:31px;font-size:20px;line-height:1;cursor:pointer}
    #ken-bypass-body{padding:13px;display:grid;gap:10px}
    #ken-bypass-body label{display:block;font-weight:700;color:#ffd36a;margin-bottom:5px}
    #ken-bypass-body input,#ken-bypass-body textarea{width:100%;border:1px solid #3d6ba7;border-radius:9px;background:#050b19;color:#fff;padding:10px;outline:none;font:13px Arial}
    #ken-bypass-body input:focus,#ken-bypass-body textarea:focus{border-color:#ffbf35;box-shadow:0 0 0 2px #ffbf3533}
    #ken-bypass-body textarea{min-height:58px;resize:vertical}
    .ken-row{display:flex;gap:8px;align-items:center}
    .ken-row input{flex:1;min-width:0}
    .ken-btn{border:1px solid #ffd16a;border-radius:10px;padding:10px 12px;color:#10101a;background:linear-gradient(180deg,#ffe47a,#e99a19);font-weight:900;cursor:pointer}
    .ken-btn.secondary{background:#10264a;color:#fff;border-color:#397ac7}
    #ken-bypass-status{border:1px solid #244a7b;background:#07142a;border-radius:9px;padding:9px;color:#cde5ff;min-height:38px;overflow-wrap:anywhere}
    #ken-bypass-result{min-height:45px}
    #ken-bypass-mini{display:none;width:70px;height:70px;border-radius:18px;border:2px solid #f0ad31;background:#06152f;box-shadow:0 0 16px #087cff99;cursor:pointer;overflow:hidden}
    #ken-bypass-mini img{width:100%;height:100%;object-fit:cover}
    #ken-bypass-root.ken-minimized #ken-bypass-panel{display:none}
    #ken-bypass-root.ken-minimized #ken-bypass-mini{display:block}
    #ken-bypass-root.ken-minimized{width:70px}
    @media(max-width:480px){#ken-bypass-root{right:7px;top:70px;width:min(340px,calc(100vw - 14px))}}
  `;

  function mount() {
    if (document.getElementById('ken-bypass-root')) return;
    const style = document.createElement('style');
    style.textContent = css;
    document.documentElement.appendChild(style);
    const root = document.createElement('div');
    root.id = 'ken-bypass-root';
    root.innerHTML = `
      <div id="ken-bypass-panel">
        <div id="ken-bypass-head">
          <img src="${LOGO}" alt="KEN BYPASS">
          <strong>KEN BYPASS</strong><span class="ken-spacer"></span>
          <button class="ken-iconbtn" id="ken-collapse" title="Thu gọn"><img src="data:image/jpeg;base64," alt="Thu gọn"></button>
          <button class="ken-iconbtn" id="ken-close" title="Ẩn bảng"><img src="data:image/png;base64," alt="Đóng"></button>
        </div>
        <div id="ken-bypass-body">
          <div>
            <label for="ken-delay">Nhập số giây đợi khi lấy mã</label>
            <div class="ken-row"><input id="ken-delay" type="number" min="1" max="3600" value="${Number(get(STORE.delay, DEFAULT_DELAY)) || DEFAULT_DELAY}"><span>giây</span></div>
          </div>
          <div>
            <label for="ken-url">Nhập link Google cần lấy mã GTraffic</label>
            <input id="ken-url" type="url" placeholder="https://www.google.com/..." value="${escapeAttr(get(STORE.url, ''))}">
          </div>
          <div class="ken-row">
            <button class="ken-btn" id="ken-start" style="flex:1">XÁC NHẬN</button>
            <button class="ken-btn secondary" id="ken-stop">DỪNG</button>
          </div>
          <div id="ken-bypass-status">Sẵn sàng. Nhập link rồi nhấn XÁC NHẬN.</div>
          <div>
            <label for="ken-code">Mã code</label>
            <textarea id="ken-code" placeholder="Mã lấy được sẽ hiện ở đây..."></textarea>
            <div class="ken-row" style="margin-top:7px">
              <button class="ken-btn secondary" id="ken-copy" style="flex:1">SAO CHÉP MÃ</button>
              <button class="ken-btn secondary" id="ken-clear">XÓA</button>
            </div>
          </div>
          <button class="ken-btn secondary" id="ken-continue" style="display:none">TÔI ĐÃ GIẢI CAPTCHA — TIẾP TỤC</button>
        </div>
      </div>
      <button id="ken-bypass-mini" title="Mở KEN BYPASS"><img src="${BANNER}" alt="KEN BYPASS"><span class="ken-mini-plus"><img src="data:image/jpeg;base64," alt="Mở rộng"></span></button>
    `;
    document.documentElement.appendChild(root);

    const $ = id => root.querySelector('#' + id);
    const status = message => { $('ken-bypass-status').textContent = message; };
    $('ken-collapse').onclick = () => root.classList.add('ken-minimized');
    $('ken-bypass-mini').onclick = () => root.classList.remove('ken-minimized');
    $('ken-close').onclick = () => { root.style.display = 'none'; };
    $('ken-delay').onchange = () => set(STORE.delay, clampDelay($('ken-delay').value));
    $('ken-url').onchange = () => set(STORE.url, $('ken-url').value.trim());
    $('ken-clear').onclick = () => $('ken-code').value = '';
    $('ken-copy').onclick = () => copyCode($('ken-code').value, status);
    $('ken-stop').onclick = () => {
      set(STORE.active, false);
      set(STORE.waiting, false);
      $('ken-continue').style.display = 'none';
      status('Đã dừng quy trình.');
    };
    $('ken-start').onclick = () => {
      const url = $('ken-url').value.trim();
      if (!/^https:\/\/(www\.)?google\.[a-z.]+\/?/i.test(url)) {
        status('Hãy nhập link Google bắt đầu bằng https://google...'); return;
      }
      const delay = clampDelay($('ken-delay').value);
      set(STORE.url, url); set(STORE.delay, delay);
      set(STORE.active, true); set(STORE.clicked, false);
      set(STORE.waiting, false); set(STORE.started, 0);
      if (!isGtraffic) {
        status('Hãy mở trang GTraffic trước, sau đó nhấn XÁC NHẬN để chạy.');
        set(STORE.active, false);
        return;
      }
      status('Đã lưu link. Đang kiểm tra nút G trên GTraffic...');
      runGtraffic(status, $('ken-continue'), $('ken-delay'), $('ken-code'));
    };
    $('ken-continue').onclick = () => {
      status('Đang kiểm tra trạng thái CAPTCHA. Hãy hoàn tất thử thách trực tiếp trên trang GTraffic; script không giải CAPTCHA thay bạn.');
      watchCaptchaThenContinue(status, $('ken-continue'), $('ken-delay'), $('ken-code'));
    };
    makeDraggable(root, $('ken-bypass-head'));
    if (get(STORE.active, false)) {
      if (isGtraffic) runGtraffic(status, $('ken-continue'), $('ken-delay'), $('ken-code'));
      else if (isGoogle) {
        status('Đang ở Google. Quy trình lấy mã cần chạy trên tab GTraffic.');
      }
    }
  }

  function clampDelay(value) {
    const n = Math.floor(Number(value));
    return Number.isFinite(n) ? Math.max(1, Math.min(3600, n)) : DEFAULT_DELAY;
  }
  function escapeAttr(s) {
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
  function makeDraggable(root, handle) {
    let x=0,y=0,drag=false;
    handle.addEventListener('pointerdown', e => {
      if (e.target.closest('button')) return;
      drag=true; x=e.clientX-root.offsetLeft; y=e.clientY-root.offsetTop;
      handle.setPointerCapture(e.pointerId);
    });
    handle.addEventListener('pointermove', e => {
      if (!drag) return;
      root.style.left=Math.max(0,e.clientX-x)+'px';
      root.style.top=Math.max(0,e.clientY-y)+'px';
      root.style.right='auto';
    });
    handle.addEventListener('pointerup', () => drag=false);
    handle.addEventListener('pointercancel', () => drag=false);
  }
  async function copyCode(value, status) {
    const code = String(value || '').trim();
    if (!code) { status('Chưa có mã để sao chép.'); return; }
    try {
      if (typeof GM_setClipboard === 'function') GM_setClipboard(code);
      else await navigator.clipboard.writeText(code);
      status('Đã sao chép mã: ' + code);
    } catch (_) { status('Không tự sao chép được. Hãy chọn và copy mã trong ô.'); }
  }
  function captchaVisible() {
    const selectors = [
      'iframe[src*="recaptcha"]', 'iframe[src*="hcaptcha"]',
      'iframe[src*="challenges.cloudflare.com"]',
      '.g-recaptcha', '.h-captcha', '[data-sitekey]',
      'input[name*="captcha" i]',
      'iframe[title*="challenge" i]', 'iframe[title*="captcha" i]'
    ];
    const visible = el => {
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      return r.width > 0 && r.height > 0 &&
        s.display !== 'none' && s.visibility !== 'hidden' &&
        Number(s.opacity || 1) > 0;
    };
    return selectors.some(selector =>
      [...document.querySelectorAll(selector)].some(visible)
    ) || /verify you are human|complete the captcha|i am not a robot|xác minh bạn không phải robot|xác nhận bạn không phải robot/i
      .test(document.body?.innerText || '');
  }

  function findGButton() {
    const nodes = [...document.querySelectorAll(
      'button,a,[role="button"],input[type="button"],input[type="submit"]'
    )];
    const score = el => {
      const img = el.querySelector('img');
      const text = [
        el.innerText, el.textContent, el.getAttribute('aria-label'),
        el.title, el.value, img?.alt
      ].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim().toLowerCase();
      const src = img?.getAttribute('src') || '';
      if (/google/.test(text) || /google/.test(src)) return 12;
      if (/^(g|g\s*go|g\s*get code|g\s*lấy mã)$/.test(text)) return 10;
      if (/^(continue with google|sign in with google)$/.test(text)) return 9;
      return 0;
    };
    return nodes
      .map(el => ({el, score: score(el)}))
      .filter(item => item.score > 0 && !item.el.disabled)
      .sort((a, b) => b.score - a.score)[0]?.el || null;
  }

  let captchaWatcherRunning = false;
  async function watchCaptchaThenContinue(status, continueBtn, delayInput, codeBox) {
    if (captchaWatcherRunning) return;
    captchaWatcherRunning = true;
    continueBtn.style.display = 'none';
    set(STORE.waiting, true);
    status('Đang chờ CAPTCHA hoàn tất. Hãy tự thao tác trực tiếp trên trang...');
    let stableClear = 0;
    for (let i = 0; i < 900; i++) {
      if (!get(STORE.active, false)) break;
      if (captchaVisible()) {
        stableClear = 0;
      } else {
        stableClear++;
        // Require a stable clear state to avoid racing page transitions.
        if (stableClear >= 4) {
          set(STORE.waiting, false);
          captchaWatcherRunning = false;
          status('Đã phát hiện CAPTCHA không còn hiển thị. Bắt đầu đếm giờ lấy mã...');
          await sleep(700);
          beginWait(status, delayInput, codeBox);
          return;
        }
      }
      await sleep(1000);
    }
    captchaWatcherRunning = false;
    if (get(STORE.active, false)) {
      continueBtn.style.display = 'block';
      status('Vẫn chưa xác nhận được CAPTCHA đã hoàn tất. Nếu trang đã đổi trạng thái, nhấn TIẾP TỤC để kiểm tra lại.');
    }
  }

  async function runGtraffic(status, continueBtn, delayInput, codeBox) {
    if (!get(STORE.active, false)) return;
    status('Đã vào GTraffic. Đang kiểm tra CAPTCHA và nút G...');
    await sleep(900);

    if (captchaVisible()) {
      set(STORE.waiting, true);
      continueBtn.style.display = 'block';
      status('Đã phát hiện CAPTCHA. Hãy tự giải trực tiếp trên trang; KEN BYPASS sẽ theo dõi trạng thái.');
      return;
    }

    if (!get(STORE.clicked, false)) {
      const button = findGButton();
      if (button) {
        button.click();
        set(STORE.clicked, true);
        status('Đã nhấn nút G. Đang theo dõi trang và CAPTCHA...');
        await sleep(1200);
      } else {
        status('Chưa tìm thấy nút G tự động. Hãy nhấn nút G trên trang; KEN BYPASS sẽ tiếp tục theo dõi.');
      }
    }

    if (captchaVisible()) {
      set(STORE.waiting, true);
      continueBtn.style.display = 'block';
      status('CAPTCHA đang hiển thị. Hãy tự giải trên trang rồi nhấn TIẾP TỤC để script kiểm tra.');
      return;
    }

    // A button may render after the page's first paint; check once more.
    if (!get(STORE.clicked, false)) {
      await sleep(1000);
      const lateButton = findGButton();
      if (lateButton) {
        lateButton.click();
        set(STORE.clicked, true);
        await sleep(1200);
      }
    }

    if (captchaVisible()) {
      set(STORE.waiting, true);
      continueBtn.style.display = 'block';
      status('Đã phát hiện CAPTCHA. Hãy tự hoàn thành trên trang rồi nhấn TIẾP TỤC.');
      return;
    }

    set(STORE.waiting, false);
    beginWait(status, delayInput, codeBox);
  }

  async function beginWait(status, delayInput, codeBox) {
    if (!get(STORE.active, false)) return;
    const seconds = clampDelay(get(STORE.delay, delayInput.value || DEFAULT_DELAY));
    set(STORE.started, Date.now());

    for (let left = seconds; left > 0; left--) {
      if (!get(STORE.active, false)) return;
      if (captchaVisible()) {
        set(STORE.waiting, true);
        status('CAPTCHA xuất hiện lại. Hãy tự giải trên trang; bộ đếm sẽ tạm dừng.');
        const root = document.getElementById('ken-bypass-root');
        const continueBtn = root?.querySelector('#ken-continue');
        if (continueBtn) continueBtn.style.display = 'block';
        return;
      }
      status('Đang đợi lấy mã: ' + left + ' giây');
      await sleep(1000);
    }

    const code = extractVisibleCode();
    if (code) {
      codeBox.value = code;
      await copyCode(code, status);
      status('Đã tìm thấy và sao chép mã: ' + code);
      set(STORE.active, false);
      set(STORE.waiting, false);
    } else {
      status('Hết giờ nhưng chưa tìm thấy mã. Trang có thể dùng định dạng khác; hãy gửi ảnh phần hiển thị mã để tao chỉnh bộ nhận diện.');
    }
  }

  function extractVisibleCode() {
    const isVisible = el => {
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      return r.width > 0 && r.height > 0 &&
        s.display !== 'none' && s.visibility !== 'hidden';
    };
    const selectors = [
      'input:not([type="password"])', 'textarea', 'code', 'pre',
      '[class*="code" i]', '[id*="code" i]',
      '[class*="token" i]', '[id*="token" i]',
      '[class*="key" i]', '[id*="key" i]'
    ];
    const values = [...new Set(selectors.flatMap(s => [...document.querySelectorAll(s)]))]
      .filter(isVisible)
      .map(el => {
        if ('value' in el && el.value) return String(el.value).trim();
        return (el.innerText || el.textContent || '').trim();
      })
      .filter(Boolean);

    const leafLabels = [...document.querySelectorAll('body *')]
      .filter(el => el.children.length === 0 && isVisible(el))
      .filter(el => /verification\s*code|your\s*code|access\s*code|mã\s*(xác nhận|truy cập)|code\s*:/i.test(el.textContent || ''))
      .map(el => (el.parentElement?.innerText || el.innerText || '').trim());

    const all = [...values, ...leafLabels, document.body?.innerText || ''];
    const patterns = [
      /(?:verification\s*code|your\s*code|access\s*code|mã(?:\s*xác nhận|\s*truy cập)?|code)\s*[:：#-]?\s*([A-Z0-9][A-Z0-9_-]{3,31})/i,
      /\b([A-Z0-9]{5,16})\b/i
    ];

    // Prefer values explicitly associated with a code label.
    for (const raw of [...values, ...leafLabels]) {
      const match = raw.match(patterns[0]);
      if (match) return match[1].trim();
    }

    // Then accept a short standalone token only from code-like fields.
    for (const raw of values) {
      const value = raw.replace(/\s+/g, '');
      if (/^[A-Z0-9][A-Z0-9_-]{4,20}$/i.test(value) &&
          !/^(HTTPS|GOOGLE|GTRAFFIC|VERIFY|SUCCESS|LOADING)$/i.test(value)) {
        return value;
      }
    }
    return '';
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mount, {once:true});
  else mount();
})();
